// ?update@LANAPI@@UAEXXZ
// partial score=0.0 date=2026-09-29
//
// PARTIAL 0.999. Copy this file to
// game/GameEngine/Source/GameNetwork/LANAPIUpdate.cpp and land it with
//   python3 tools/add_match.py '?update@LANAPI@@UAEXXZ' 0x006870F0 2436 \
//     game/GameEngine/Source/GameNetwork/LANAPIUpdate.cpp --replace-existing
// once the last byte falls (see the bottom of this header). It must NOT sit in
// game/ before then: a game/ source with no matched row fails Source claims.
//
// Every callee now resolves, which is what the previous three sessions could
// not get past. The 3 symbols.csv pins and every name below already landed:
//   ?handleRequestJoin@LANAPI@@IAEXPAULANMessage@@PAUBfmeNetAddress@@@Z 0x0068C400
//   ?handleRequestGameLeave@LANAPI@@IAEXPAULANMessage@@PAUBfmeNetAddress@@_N@Z 0x0068BAC0
//   ?_bfme_messageHandler_0068AD80@LANAPI@@IAEXPAULANMessage@@PBUTransportAddress@@@Z 0x0068AD80
// The gate's only remaining complaint is one non-relocation byte at +0x7A1:
//   retail  lea ecx, [edi + eax + 0x88]   (SIB 07: base edi,  index eax)
//   ours   lea ecx, [eax + edi + 0x88]   (SIB 38: base eax,  index edi)
// edi is the strength-reduced slot byte offset the loop carries; eax is
// m_currentGame reloaded from [esi+0x40] one instruction earlier. Retail puts
// the loop-carried register in the base, ours puts the freshly reloaded one
// there, and no C++ expression reaches it: twelve spellings of this argument
// (member, GameSlot*, BfmeNetAddress*, and six integer reorderings) all compile
// byte-identically, and seven micro shapes show the rule is the reload, not the
// spelling. Rewriting the loop so the induction variable IS the byte offset
// does flip the order, but then the body loses 613 bytes and diverges at
// +0x30. Full measurement in
// targets/game/reverse/identity_evidence/006870F0-callees.md.
// This is docs/shape_levers.md "The two-register lea operand order is not a
// spelling"; do not spend a session on that byte.
// LANAPI::update, retail 0x006870F0, 2436 bytes (code ends at the ret 00687A25;
// the 19-entry switch table 00687A28..00687A74 is the rest of the body, then
// int3 padding). The readable-body note on the lift names lanapi.cpp, but that
// TU is the Zero Hour layout: its LANAPIInterface declares the handler
// arguments as UnsignedInt senderIP and its OnChat as (UnicodeString, UnsignedInt,
// UnicodeString, ChatType), while retail calls every handler with a pointer to a
// six-byte {ip,port} pair and passes that same pointer as OnChat's second
// argument. The witnesses for the BFME shape are in the body itself, so this
// file carries the mirror class the way LANAPIRequestGameLeave.cpp and
// LANAPIAddPlayer.cpp do, and lanapi.cpp keeps its own layout.
//
// Callee identities, all witnessed:
//  * handler names come from the ledger row already at each target address
//    (handleRequestLocations 0x0068AEF0, handleGameAnnounce 0x0068C110,
//    handleLobbyAnnounce 0x0068B1E0, handleRequestGameInfo 0x0068B380,
//    handleJoinAcceptRva0068CF00 0x0068CF00, handleJoinDeny 0x0068B4C0,
//    handleRequestLobbyLeave 0x0068AC20, handleSetAccept 0x0068AC80,
//    handleHasMap 0x0068B540, handleChat 0x0068B6A0, handleGameOptions
//    0x0068B890, handleInActive 0x0068B920, handleGameStart 0x0068BFA0 by the
//    symbols.csv pin written for this very call site);
//  * handleRequestJoin (0x0068C400) and handleRequestGameLeave (0x0068BAC0)
//    are named from the Zero Hour twin: the 0x0068C400 body is
//    handleRequestJoin statement for statement (GameToJoin.gameIP against the
//    local address, then JOIN_DENY/JOIN_ACCEPT replies, the GlobalData CRC
//    compare and the per-slot serial scan), and 0x0068BAC0 is
//    handleRequestGameLeave (OnHostLeave, removeGame, delete m_currentGame,
//    LookupPlayer/local-IP re-add, else the open-slot/OnPlayerLeave/
//    RequestGameOptions branch, else the m_games walk comparing getName() with
//    GameToLeave.gameName). See
//    targets/game/reverse/identity_evidence/006870F0-callees.md;
//  * 0x0068ACF0, 0x0068ADE0 and 0x0068AD80 keep the address-keyed names the
//    ledger already carries for those bodies; no descriptive name is claimed
//    for them.
// update itself is vtable slot 5 of the LANAPI table 0x0111AF50, which is why
// it is virtual and public here.
#include <wchar.h>
#include "Common/AsciiString.h"
#include "Common/UnicodeString.h"
#include <wchar.h>
extern "C" __declspec(dllimport) unsigned __stdcall timeGetTime();
extern bool LANbuttonPushed;
extern bool LANSocketErrorDetected;
extern unsigned Rva012F772C;

// The sender pair every handler takes: six bytes of {ip, port} built by update
// on its own stack and handed to the callee by pointer.
struct BfmeNetAddress { unsigned ip; unsigned short port; BfmeNetAddress():ip(0),port(0){} BfmeNetAddress(unsigned a,unsigned short b):ip(a),port(b){} };
// Second spelling of that same argument, kept because the two address-keyed
// LANAPI handler names already in the ledger (0x0068ACF0, 0x0068ADE0) use it.
struct TransportAddress { unsigned ip; unsigned short port; };
// Same six bytes, so the address update already built is the argument; the cast
// only keeps the two spellings apart in the mangled name.
#define UTRANSPORTADDRESS(a) (const TransportAddress *)&(a)
// ...and the same address spelled as the plain integer the ledger names use.
#define SENDERIP(a) (unsigned)&(a)
#pragma pack(push,1)
struct RvaLANIncoming { char data[0x400]; unsigned length; unsigned ip; unsigned short port; char gap40A[4]; };
#pragma pack(pop)
struct LANMessage { union { double alignment; struct { int type; wchar_t name[13]; char rest[0x1e0-30]; }; }; };
class Transport {
public:
  bool update();
  char prefix[0x20704];
  RvaLANIncoming incoming[128];
};
struct LANPlayer { UnicodeString name, login, host; unsigned lastHeard; LANPlayer *next; unsigned ip; };
class GameSlot {
public:
  bool isHuman() const;
  char prefix[0x30];
  BfmeNetAddress address;
  char gap38[0x2c];
  unsigned lastHeard;
  unsigned getLastHeard() { return isHuman()?lastHeard:0; }
};
class LANGameInfo {
public:
  ~LANGameInfo();
  UnicodeString getPlayerName(int);
  char prefix[0xd];
  bool inProgress;
  char gapE[0x58-0xe];
  GameSlot slots[8];
  unsigned getLastHeard() const {return lastHeard;}
  unsigned getLastHeard(int p) { return slots[p].isHuman()?slots[p].lastHeard:0; }
  LANGameInfo *next;
  unsigned lastHeard;
};
class RvaLANGameText {
public:
  virtual void slot00();
  virtual void slot01();
  virtual void slot02();
  virtual void slot03();
  virtual void slot04();
  virtual void slot05();
  virtual void slot06();
  virtual void slot07();
  virtual void slot08();
  virtual void slot09();
  virtual UnicodeString fetch(const char *, bool = false);
};
extern RvaLANGameText *TheGameText;
class LANAPI
{
public:
  virtual void slot00();
  virtual void slot04();
  virtual void slot08();
  virtual void slot0C();
  virtual void slot10();
  virtual void update();
  virtual void slot18();
  virtual void slot1C();
  virtual void slot20();
  virtual void slot24();
  virtual void slot28();
  virtual void slot2C();
  virtual void slot30();
  virtual void slot34();
  virtual void slot38();
  virtual void slot3C();
  virtual void slot40();
  virtual void slot44();
  virtual void RequestGameStart();
  virtual void RequestGameStartTimer(int);
  virtual void RequestGameOptions(AsciiString, bool, const BfmeNetAddress & = BfmeNetAddress());
  virtual void RequestGeneratedOptions(bool, const BfmeNetAddress & = BfmeNetAddress());
  virtual void slot58();
  virtual void RequestGameAnnounce();
  virtual void RequestSetName(UnicodeString);
  virtual void RequestLobbyLeave(bool);
  virtual void ResetGameStartTimer();
  virtual void OnGameList(LANGameInfo *);
  virtual void OnPlayerList(LANPlayer *);
  virtual void OnGameJoin(int, LANGameInfo *, void *);
  virtual void slot78();
  virtual void slot7C();
  virtual void OnPlayerLeave(UnicodeString);
  virtual void slot84();
  virtual void slot88();
  virtual void OnChat(UnicodeString, const BfmeNetAddress *, UnicodeString, int);
  virtual void slot90();
  virtual void slot94();
  virtual void slot98();
  virtual void slot9C();
  virtual void slotA0();
  virtual void slotA4();
  virtual void slotA8();
  virtual void slotAC();
  virtual void slotB0();
  virtual void slotB4();
  virtual bool AmIHost();
  virtual void slotBC();
  virtual void slotC0();
  virtual void fillInLANMessage(LANMessage *);
  virtual void checkMOTD();
  virtual void slotCC();
  virtual void slotD0();
  virtual void slotD4();
  virtual void slotD8();
  virtual const BfmeNetAddress *localAddress();
  unsigned field04;
  LANPlayer *m_lobbyPlayers;
  LANGameInfo *m_games;
  UnicodeString m_name;
  AsciiString m_userName, m_hostName;
  unsigned m_gameStartTime;
  int m_gameStartSeconds;
  int m_pendingAction;
  unsigned m_expiration;
  char gap2C[12];
  unsigned m_lastResendTime;
  bool m_isInLANMenu, m_inLobby;
  char gap3E[2];
  LANGameInfo *m_currentGame;
  char gap44[8];
  Transport *m_transport;
  unsigned m_broadcastAddr, m_lastUpdate;
protected:
  void removeGame(LANGameInfo *);
  void handleRequestLocations(LANMessage *, BfmeNetAddress *);
  void handleGameAnnounce(LANMessage *, BfmeNetAddress *);
  void handleLobbyAnnounce(LANMessage *, BfmeNetAddress *);
  void handleRequestGameInfo(LANMessage *, unsigned);
  void handleRequestJoin(LANMessage *, BfmeNetAddress *);
  void handleJoinAcceptRva0068CF00(LANMessage *, BfmeNetAddress *);
  void handleJoinDeny(LANMessage *, unsigned);
  // The third argument is the one retail's own switch sets to 1 for message
  // type 8 and leaves 0 for type 6; what it selects inside the body is not
  // established, so it stays an unnamed bool here.
  void handleRequestGameLeave(LANMessage *, BfmeNetAddress *, bool);
  void handleRequestLobbyLeave(LANMessage *, BfmeNetAddress *);
  void handleSetAccept(LANMessage *, BfmeNetAddress *);
  void handleHasMap(LANMessage *, unsigned);
  void handleChat(LANMessage *, unsigned);
  void _bfme_handleHasMap_0068ACF0(LANMessage *, const TransportAddress *);
  void handleGameStart(LANMessage *, unsigned);
  void _bfme_messageHandler_0068AD80(LANMessage *, const TransportAddress *);
  void handleGameOptions(LANMessage *, unsigned);
  void handleInActive(LANMessage *, unsigned);
  void _bfme_handleSerializedGameInfo_0068ADE0(LANMessage *, const TransportAddress *);
  void removePlayer(LANPlayer *player) {
   if (m_lobbyPlayers == player) m_lobbyPlayers = m_lobbyPlayers->next;
   else {
    LANPlayer *p = m_lobbyPlayers;
    while (p->next && p->next != player) p = p->next;
    if (p->next == player) p->next = player->next;
   }
  }
};
template<> inline const char *StringBase<char>::str() const { return m_data ? m_data->data : ""; }
template<> inline const wchar_t *StringBase<wchar_t>::str() const { return m_data ? m_data->data : L""; }
void LANAPI::update()
{
  if (LANbuttonPushed) return;
  unsigned now = timeGetTime();
  if (now > m_lastUpdate + 200) m_lastUpdate = now; else return;
  if (!m_transport->update() && !LANSocketErrorDetected && m_isInLANMenu == true)
   LANSocketErrorDetected = true;
  for (int i=0; i<128 && !LANbuttonPushed; ++i) {
   bool leaveFlag = false;
   if (m_transport->incoming[i].length > 0) {
    BfmeNetAddress sender(m_transport->incoming[i].ip, m_transport->incoming[i].port);
    const BfmeNetAddress *local = localAddress();
    if (sender.ip == local->ip && sender.port == local->port) {
     m_transport->incoming[i].length = 0;
     continue;
    }
    LANMessage *msg = (LANMessage *)m_transport->incoming[i].data;
    switch (msg->type) {
    case 0: handleRequestLocations(msg, &sender); break;
    case 1: handleGameAnnounce(msg, &sender); break;
    case 2: handleLobbyAnnounce(msg, &sender); break;
    case 17: handleRequestGameInfo(msg, SENDERIP(sender)); break;
    case 3: handleRequestJoin(msg, &sender); break;
    case 4: RequestLobbyLeave(true); handleJoinAcceptRva0068CF00(msg, &sender); break;
    case 5: handleJoinDeny(msg, SENDERIP(sender)); break;
    case 8: leaveFlag = true;
    case 6: handleRequestGameLeave(msg, &sender, leaveFlag); break;
    case 7: handleRequestLobbyLeave(msg, &sender); break;
    case 9: handleSetAccept(msg, &sender); break;
    case 10: handleHasMap(msg, SENDERIP(sender)); break;
    case 11: handleChat(msg, SENDERIP(sender)); break;
    case 12: _bfme_handleHasMap_0068ACF0(msg, UTRANSPORTADDRESS(sender)); break;
    case 13: handleGameStart(msg, SENDERIP(sender)); break;
    case 14: _bfme_messageHandler_0068AD80(msg, UTRANSPORTADDRESS(sender)); break;
    case 15: handleGameOptions(msg, SENDERIP(sender)); break;
    case 16: handleInActive(msg, SENDERIP(sender)); break;
    case 18: _bfme_handleSerializedGameInfo_0068ADE0(msg, UTRANSPORTADDRESS(sender)); break;
    }
    m_transport->incoming[i].length = 0;
   }
  }
  if (LANbuttonPushed) return;
  if (now > 2000 + m_lastResendTime) {
   m_lastResendTime = now;
   if (m_inLobby) RequestSetName(m_name);
   else if (m_currentGame && !m_currentGame->inProgress) {
    if (AmIHost()) { RequestGeneratedOptions(true); RequestGameAnnounce(); }
    else {
     AsciiString text;
     text.format("User=%s", m_userName.str());
     RequestGameOptions(text,true);
     text.format("Host=%s", m_hostName.str());
     RequestGameOptions(text,true);
     RequestGameOptions("HELLO",false);
    }
   } else if (m_currentGame) RequestGameAnnounce();
  }
  bool playerListChanged=false, gameListChanged=false;
  LANPlayer *player = m_lobbyPlayers;
  while (player) {
   if (player->lastHeard + 20000 < now) {
    removePlayer(player);
    LANPlayer *next = player->next;
    delete player;
    player = next;
    playerListChanged = true;
   } else player = player->next;
  }
  LANGameInfo *game = m_games;
  while (game) {
   if (game != m_currentGame && game->getLastHeard() + 20000 < now) {
    removeGame(game);
    LANGameInfo *next = game->next;
    delete game;
    game = next;
    gameListChanged = true;
   } else game = game->next;
  }
  if (m_currentGame && !m_currentGame->inProgress) {
   if (!AmIHost() && m_currentGame->getLastHeard(0) + 20000 < now) {
    LANMessage msg;
    fillInLANMessage(&msg);
    msg.type = 8;
    wcsncpy(msg.name, m_currentGame->getPlayerName(0).str(), 12);
    msg.name[12] = 0;
    handleRequestGameLeave(&msg, &m_currentGame->slots[0].address, false);
    UnicodeString text;
    text = TheGameText->fetch("LAN:HostNotResponding");
    OnChat(UnicodeString::TheEmptyString, localAddress(), text, 2);
   } else if (AmIHost()) {
    for (int p=1; p<8; ++p) {
     if ((m_currentGame->slots[p].address.ip || m_currentGame->slots[p].address.port) &&
       m_currentGame->getLastHeard(p) + 20000 < now) {
      LANMessage msg;
      fillInLANMessage(&msg);
      UnicodeString text;
      text.format(TheGameText->fetch("LAN:PlayerDropped"),m_currentGame->getPlayerName(p).str());
      msg.type = 6;
      wcsncpy(msg.name,m_currentGame->getPlayerName(p).str(),12);
      msg.name[12]=0;
      handleRequestGameLeave(&msg,&m_currentGame->slots[p].address,false);
      OnChat(UnicodeString::TheEmptyString,localAddress(),text,2);
     }
    }
   }
  }
  if (playerListChanged) OnPlayerList(m_lobbyPlayers);
  if (gameListChanged) OnGameList(m_games);
  if (m_pendingAction && now > m_expiration) {
   switch(m_pendingAction) {
   case 1: OnGameJoin(1,0,0); m_pendingAction=0; m_currentGame=0; m_inLobby=true; break;
   case 3: OnPlayerLeave(m_name); m_pendingAction=0; m_currentGame=0; m_inLobby=true; break;
   case 2: OnGameJoin(1,0,0); m_pendingAction=0; m_currentGame=0; m_inLobby=true; break;
   default: m_pendingAction=0;
   }
  }
  if (m_gameStartTime && m_gameStartSeconds && m_gameStartTime <= now) RequestGameStartTimer(m_gameStartSeconds);
  else if (m_gameStartTime && m_gameStartTime <= now) { ResetGameStartTimer(); RequestGameStart(); }
  if (now > Rva012F772C + 30000) { checkMOTD(); Rva012F772C=now; }
}
